<?php require_once __DIR__.'/../../app/bootstrap.php';if(admin()){header('Location:/admin/index.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(hash_equals(cfg('admin_username'),trim($_POST['username']??''))&&password_verify($_POST['password']??'',cfg('admin_password_hash'))){session_regenerate_id(true);$_SESSION['admin']=1;header('Location:/admin/index.php');exit;}$err='اطلاعات ورود اشتباه است.';}?><!doctype html><html lang=fa dir=rtl><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>ورود</title><style>body{font-family:Tahoma;background:#eef7ff}.box{max-width:420px;margin:80px auto;background:#fff;padding:30px;border-radius:22px}input{width:100%;box-sizing:border-box;padding:12px;margin:8px 0 15px}button{width:100%;padding:12px;background:#1687d9;color:#fff;border:0;border-radius:9px}.err{color:#b22}</style><div class=box><h2>پنل کافی‌نت سیداصیل</h2><?php if($err):?><p class=err><?=e($err)?></p><?php endif;?><form method=post><input type=hidden name=csrf value="<?=e(csrf())?>"><input name=username placeholder="نام کاربری" required><input type=password name=password placeholder="رمز عبور" required><button>ورود</button></form></div>
